import { Hono } from "hono";
import { zValidator } from "@hono/zod-validator";
import { authMiddleware } from "../middleware/auth.middleware.js";
import * as controller from "../controllers/digitalAsset.controller.js";
import { createDigitalAssetSchema, updateDigitalAssetSchema, idSchema } from "../validators/digitalAsset.validator.js";
const digitalAssetRoute = new Hono();
digitalAssetRoute.get("/", controller.getAll);
digitalAssetRoute.get("/:id", controller.getOne);
digitalAssetRoute.post("/", authMiddleware, zValidator("form", createDigitalAssetSchema), controller.create);
digitalAssetRoute.patch("/:id", authMiddleware, zValidator("param", idSchema), zValidator("form", updateDigitalAssetSchema), controller.update);
digitalAssetRoute.patch("/:id/like", controller.like);
digitalAssetRoute.delete("/:id", authMiddleware, zValidator("param", idSchema), controller.remove);
export default digitalAssetRoute;
